"use strict";

function formatCents(cents, symbol) {
  const sign = cents < 0 ? "-" : "";
  const abs = Math.abs(cents);
  const dollars = Math.floor(abs / 100).toString();
  const remainder = (abs % 100).toString().padStart(2, "0");
  return `${sign}${symbol}${dollars}.${remainder}`;
}

function formatUsdCents(cents) {
  return formatCents(cents, "$");
}

function formatEurCents(cents) {
  return formatCents(cents, "\u20ac");
}

module.exports = { formatUsdCents, formatEurCents };
